html:
{#- EN 10204 3.1 Material Test Certificate (QI SPEC v2, Phase C2). Rows of item groups that issue one. -#}
<style>
	.mtc { font-family: "Helvetica Neue", Arial, sans-serif; font-size: 8.8pt; color: #111; }
	.mtc-band { width: 100%; border-bottom: 2pt solid #1f3d2b; padding-bottom: 5pt; margin-bottom: 8pt; }
	.mtc-band td { vertical-align: bottom; }
	.mtc-co { font-size: 12pt; font-weight: 800; color: #1f3d2b; }
	.mtc-title { font-size: 13pt; font-weight: 800; letter-spacing: 0.8pt; text-align: right; }
	.mtc-sub { font-size: 7.2pt; color: #555; }
	table.mtc-meta, table.mtc-t { width: 100%; border-collapse: collapse; margin: 3pt 0 8pt; }
	.mtc-meta td { border: 0.6pt solid #000; padding: 3pt 5pt; font-size: 8pt; vertical-align: top; }
	.mtc-lbl { font-size: 6pt; text-transform: uppercase; letter-spacing: 0.4pt; color: #555; font-weight: 700; display: block; }
	.mtc-t th, .mtc-t td { border: 0.5pt solid #666; padding: 2.5pt 4pt; font-size: 7.6pt; text-align: left; vertical-align: top; }
	.mtc-t th { background: #f2f2f2; font-size: 6.4pt; text-transform: uppercase; letter-spacing: 0.3pt; }
	.mtc-h { font-size: 9pt; font-weight: 700; margin: 9pt 0 2pt; color: #1f3d2b; page-break-after: avoid; }
	.mtc-h2 { font-size: 7.6pt; font-weight: 700; margin: 4pt 0 1pt; text-transform: uppercase; letter-spacing: 0.3pt; color: #444; }
	.mtc-gap { color: #b26a00; font-size: 7.4pt; }
	.mtc-ok { color: #1f5d3f; font-weight: 700; }
	.mtc-nok { color: #c0262d; font-weight: 700; }
	.mtc-statement { border: 0.8pt solid #1f3d2b; background: #f4f6f4; padding: 6pt 8pt; font-size: 8.4pt; margin: 12pt 0; }
	table.mtc-sign { width: 100%; margin-top: 16pt; }
	.mtc-sign td { width: 50%; font-size: 7.8pt; vertical-align: bottom; padding-top: 22pt; }
	.mtc-line { border-top: 0.6pt solid #000; padding-top: 2pt; width: 75%; }
	.mtc-foot { margin-top: 10pt; border-top: 0.5pt solid #999; padding-top: 3pt; font-size: 6.2pt; color: #666; }
</style>
<div class="mtc">
<table class="mtc-band"><tr>
	<td><div class="mtc-co">{{ doc.company }}</div><div class="mtc-sub">Quality Management System &middot; ISO 9001:2015</div></td>
	<td class="mtc-title">MATERIAL TEST CERTIFICATE<div class="mtc-sub" style="text-align:right;letter-spacing:0;font-weight:400">Inspection certificate type 3.1 to EN 10204</div></td>
</tr></table>
<table class="mtc-meta"><tr>
	<td style="width:36%"><span class="mtc-lbl">Customer</span><strong>{{ doc.customer_name or doc.customer }}</strong></td>
	<td style="width:22%"><span class="mtc-lbl">Certificate / Delivery Note No.</span><strong>{{ doc.name }}</strong><div class="mtc-sub">Date: {{ doc.get_formatted("posting_date") }}</div></td>
	<td style="width:22%"><span class="mtc-lbl">Customer PO</span>{{ doc.po_no or "&mdash;" }}</td>
	<td style="width:20%"><span class="mtc-lbl">Manufacturer / supplier</span>{{ doc.company }}</td>
</tr></table>
{%- set ns = namespace(n=0) -%}
{%- for row in doc.items -%}
{%- set m = mtc_row(row) -%}
{%- if m -%}
{%- set ns.n = ns.n + 1 -%}
<div class="mtc-h">{{ ns.n }}. {{ m.item_code }} &mdash; {{ m.item_name }}
	<span class="mtc-sub">&middot; {{ frappe.format(m.qty, {"fieldtype": "Float"}) }} {{ m.uom }}{% if m.batches %} &middot; Batch {{ m.batches | join(", ") }}{% endif %}{% if m.heat_nos %} &middot; Heat {{ m.heat_nos | join(", ") }}{% endif %}</span></div>
<div class="mtc-h2">Material traceability</div>
<table class="mtc-t"><thead><tr><th style="width:12%">Role</th><th style="width:16%">Material</th><th style="width:12%">Batch / heat</th><th style="width:22%">Supplier</th><th style="width:16%">Receipt</th><th>Supplier's 3.1 certificate</th></tr></thead><tbody>
{%- for s in m.sources %}<tr><td>{{ s.role }}</td><td>{{ s.item }}<div class="mtc-sub">{{ s.item_name or "" }}</div></td><td>{{ s.batch }}{% if s.heat_no %}<div class="mtc-sub">heat {{ s.heat_no }}</div>{% endif %}</td>
	<td>{{ s.supplier or "&mdash;" }}</td><td>{{ s.receipt }}<div class="mtc-sub">{{ frappe.format(s.receipt_date, {"fieldtype": "Date"}) }}</div></td>
	<td>{% if s.certificate %}{{ s.certificate_name }}{% else %}<span class="mtc-gap">not on file</span>{% endif %}</td></tr>
{%- else %}<tr><td colspan="6" class="mtc-gap">No receipt trace for this delivery.</td></tr>{%- endfor %}
</tbody></table>
<div class="mtc-h2">Material properties</div>
<table class="mtc-t"><thead><tr><th>Property</th><th style="width:18%">Method</th><th style="width:16%">Requirement</th><th style="width:14%">Result</th><th style="width:12%">Source</th><th style="width:10%">Conforms</th></tr></thead><tbody>
{%- for p in m.properties %}<tr><td>{{ p.property }}</td><td>{{ p.method or "&mdash;" }}</td><td>{{ p.limits }} {{ p.unit }}</td><td>{{ p.result or "&mdash;" }} {{ p.unit if p.result }}</td><td>{{ p.source }}</td>
	<td>{% if p.ok %}<span class="mtc-ok">Yes</span>{% else %}<span class="mtc-nok">No</span>{% endif %}</td></tr>
{%- else %}<tr><td colspan="6" class="mtc-gap">No material properties recorded; see the supplier's certificate referenced above.</td></tr>{%- endfor %}
</tbody></table>
{%- endif -%}
{%- endfor -%}
{%- if not ns.n -%}<p>No item on {{ doc.name }} belongs to an item group that issues a 3.1 certificate.</p>{%- endif -%}
<div class="mtc-statement">We certify that the material supplied under this delivery note complies with the requirements of the order.
The results above are taken from the supplier's inspection certificates referenced and from our own tests, and are traceable to
the batches and heats listed. This certificate is issued in accordance with EN 10204 type 3.1.</div>
<table class="mtc-sign"><tr>
	<td><div class="mtc-line">Stores Manager</div></td>
	<td><div class="mtc-line">For {{ doc.company }} &mdash; authorised inspection representative</div></td>
</tr></table>
<div class="mtc-foot">HCCPL/QMS/FRM-039 &middot; Issue 01 / Rev 00 &middot; Material Test Certificate (EN 10204 3.1) &middot; {{ doc.name }} &middot; generated {{ frappe.utils.now_datetime().strftime("%d-%m-%Y %H:%M") }}</div>
</div>
